style.css:
@-moz-document domain("pinterest.com") {
:root {
    -bg: rgb(0, 0, 30);
    -bg-alt: #1b003c;
    -highlight: blueviolet;
    -text: #d6d6ff;
    -muted: #aaa0cc;
    -radius: 6px;
  }

  body {
    background-color: var(--bg) !important;
    color: var(--text) !important;
    font-family: system-ui, sans-serif !important;
    scrollbar-color: var(--highlight) var(--bg-alt) !important;
  }

  /* Buttons */
  button, .Button, [role="button"] {
    background-color: rgb(19, 19, 66) !important;
    border: 1px solid var(--highlight) !important;
    border-radius: var(--radius) !important;
    color: var(--highlight) !important;
    transition: 0.2s ease;
  }
  button:hover {
    filter: brightness(1.2) !important;
  }

  /* Links & text */
  a, .JlN, .X8m, .BNH, .g_1, .B1n, .Uvi, .V0G, .ePF, .bW6 {
    color: var(--highlight) !important;
  }

  /* Cards / Pins */
  div[data-test-id="pin"], [data-test-id="board-card"] {
    background-color: var(--bg-alt) !important;
    border-radius: var(--radius) !important;
    border: 1px solid var(--highlight)20 !important;
  }

  /* Headers / nav */
  header, nav {
    background-color: var(--bg-alt) !important;
    border-bottom: 1px solid var(--highlight)40 !important;
  }

  /* Inputs */
  input, textarea {
    background-color: var(--bg-alt) !important;
    border: 1px solid var(--highlight) !important;
    color: var(--text) !important;
    border-radius: var(--radius) !important;
  }

  /* Images */
  img {
    border: 1px solid var(--highlight)40 !important;
    border-radius: var(--radius) !important;
  }

  /* Misc containers */
  .imm, .Il7, .fSK, .a_A, .yBD, .haa, .sKP, .NSs {
    background-color: var(--bg-alt) !important;
  }
}
